#include <iostream>
#include <string>
using namespace std;

int find_substring(const string& s1, const string& s2, int start) {
    for (int i = start; i <= (int)s1.size() - (int)s2.size(); ++i) {
        if (s1[i] == s2[0]) {
            bool match = true;
            for (int j = 1; j < (int)s2.size(); ++j) {
                if (s1[i + j] != s2[j]) {
                    match = false;
                    break;
                }
            }
            if (match) return i;
        }
    }
    return -1;
}

int main() {
    string s1, s2, result;
    cin >> s1;
    int pos = find_substring(s1, "at", 1);
    s2 = s1.substr(0, pos) + '@' + s1.substr(pos + 2);
    int index = find_substring(s2, "dot", 1);
    int last_pos = 0;
    while (index != -1 && index < (int)s2.size() - 3) {
        result += s2.substr(last_pos, index - last_pos) + ".";
        last_pos = index + 3;
        index = find_substring(s2, "dot", last_pos);
    }
    result += s2.substr(last_pos);
    cout << result;
    return 0;
}
